// The fonts of the Átrios site (site-atrios), for the certificate PDF only:
// Space Grotesk for titles, IBM Plex Sans for text, IBM Plex Mono for the
// code. Both families are under the SIL Open Font License 1.1 (texts in
// ./licencas/), which allows embedding them in documents.
//
// Cut to the characters Portuguese needs (Basic Latin, Latin-1, curly quotes,
// dashes, bullet, ellipsis) with fontTools' pyftsubset, so the PDF carries a
// few dozen kilobytes. A module, not a file read at runtime, for the reason
// signature.ts gives: it rides in the server bundle with nothing to trace.

/** SpaceGrotesk-Bold.ttf */
export const GROTESK_BOLD_TTF_BASE64 =
  "";

/** IBMPlexSans-Regular.ttf */
export const PLEX_SANS_TTF_BASE64 =
  "";

/** IBMPlexSans-SemiBold.ttf */
export const PLEX_SANS_SEMIBOLD_TTF_BASE64 =
  "";

/** IBMPlexMono-Medium.ttf */
export const PLEX_MONO_MEDIUM_TTF_BASE64 =
  "";
